<?php $page_title = t('profile'); require __DIR__ . '/layout_header.php'; $u = current_user(); $avatar = ($u['avatar'] ?? '') ?: 'assets/img/avatars/avatar-' . ($u['role'] ?? 'estudiante') . '.svg'; $name = ($u['full_name'] ?? '') ?: ($u['username'] ?? 'Usuario'); ?>
<section class="card animate-in"><h2 class="metal-text"><?= e(t('profile')) ?></h2><div style="display:flex;align-items:center;gap:20px;margin-bottom:20px"><img src="<?= e($avatar) ?>" alt="Avatar" style="width:80px;height:80px;border-radius:50%;object-fit:cover;border:3px solid var(--primary)" onerror="this.src='assets/img/avatars/avatar-<?= e($u['role'] ?? 'estudiante') ?>.svg'"><div><h3 style="margin:0"><?= e($name) ?></h3><p style="margin:4px 0 0;color:var(--muted)"><?= e($u['role'] ?? '') ?></p></div></div><form method="post" class="form-grid" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="action" value="update"><label class="field"><span><?= e(t('full_name')) ?></span><input class="input" type="text" name="full_name" value="<?= e($name) ?>"></label><label class="field"><span>Email</span><input class="input" type="email" name="email" value="<?= e($u['email'] ?? '') ?>"></label><label class="field"><span><?= e(t('avatar_url')) ?></span><input class="input" type="url" name="avatar_url" value="<?= e(strpos($u['avatar'] ?? '', 'http')===0 ? $u['avatar'] : '') ?>" placeholder="https://..."></label><label class="field"><span><?= e(t('upload_avatar')) ?></span><input class="input" type="file" name="avatar_file" accept="image/png,image/jpeg,image/webp"></label><hr style="border:0;border-top:1px solid var(--line);margin:10px 0"><label class="field"><span><?= e(t('password')) ?> actual</span><input class="input" type="password" name="current_password" autocomplete="current-password"></label><label class="field"><span><?= e(t('new_password')) ?></span><input class="input" type="password" name="new_password" minlength="6" autocomplete="new-password"></label><div class="form-actions"><button class="btn btn-metal" type="submit"><?= e(t('save')) ?></button></div></form></section><?php require __DIR__ . '/layout_footer.php'; ?>
